#!/usr/bin/env python3
"""Fetch data from the local order service into a data directory.

usage:
  recon.py fetch-orders    DATA_DIR
  recon.py fetch-customers DATA_DIR     (reads DATA_DIR/needed_customers.json)

Behaviour handled by the client:
  * 429  -> sleep for the advertised Retry-After / retry_after, then repeat
  * 401/403 -> token rejected (expired): fetch a fresh token, then repeat
  * 5xx, network errors, malformed bodies -> back off briefly, then repeat
  * 404 on a customer -> re-checked a few times before being recorded as unknown
Everything is logged to DATA_DIR/events.log.
"""
import http.client
import json
import os
import sys
import time
import urllib.error
import urllib.parse
import urllib.request

BASE = "http://localhost:8080"
TIMEOUT = 30
MAX_ERRORS = 40            # transient errors tolerated per logical request
MAX_THROTTLES = 300        # consecutive 429s tolerated per logical request
MAX_AUTH_REJECTS = 6       # consecutive 401/403s tolerated per logical request
NOT_FOUND_CONFIRMATIONS = 3


def retry_after_seconds(headers, body):
    vals = []
    h = headers.get("Retry-After")
    if h is not None:
        try:
            vals.append(float(h))
        except ValueError:
            pass
    try:
        j = json.loads(body)
        if isinstance(j, dict) and "retry_after" in j:
            vals.append(float(j["retry_after"]))
    except (ValueError, TypeError):
        pass
    return max(max(vals), 0.1) if vals else 1.0


class Client:
    def __init__(self, log_path):
        self.token = None
        self.log = open(log_path, "a")
        self.counts = {}

    def note(self, kind, detail=""):
        self.counts[kind] = self.counts.get(kind, 0) + 1
        self.log.write(f"{time.strftime('%H:%M:%S')} {kind} {detail}\n")
        self.log.flush()

    def raw(self, method, path):
        headers = {}
        if self.token and path != "/token":
            headers["Authorization"] = "Bearer " + self.token
        data = b"" if method == "POST" else None
        req = urllib.request.Request(BASE + path, data=data, method=method, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=TIMEOUT) as resp:
                return resp.status, resp.headers, resp.read()
        except urllib.error.HTTPError as e:
            return e.code, e.headers, e.read()

    def call(self, method, path, check=None, not_found_ok=False):
        """Return (parsed_json, raw_body); parsed_json is None for a confirmed 404."""
        errors = throttles = rejects = not_found = 0
        while True:
            if path != "/token" and self.token is None:
                self.token = self.fetch_token()
            try:
                status, headers, body = self.raw(method, path)
            except (urllib.error.URLError, OSError, http.client.HTTPException) as e:
                errors += 1
                self.note("net_error", f"{method} {path} {e!r}")
                if errors >= MAX_ERRORS:
                    raise
                time.sleep(min(0.25 * 2 ** errors, 5))
                continue

            if status == 429:
                throttles += 1
                wait = retry_after_seconds(headers, body)
                self.note("rate_limited", f"{method} {path} wait={wait}")
                if throttles > MAX_THROTTLES:
                    raise RuntimeError(f"still rate limited after {throttles} waits: {path}")
                time.sleep(wait)
                continue

            if status in (401, 403) and path != "/token":
                rejects += 1
                self.note("auth_rejected", f"{method} {path} {status} {body[:120]!r}")
                if rejects > MAX_AUTH_REJECTS:
                    raise RuntimeError(f"auth keeps being rejected: {path}")
                self.token = None
                continue

            if status == 404 and not_found_ok:
                not_found += 1
                if not_found >= NOT_FOUND_CONFIRMATIONS:
                    self.note("not_found_confirmed", path)
                    return None, body
                self.note("not_found_recheck", path)
                time.sleep(0.5)
                continue

            if status == 200:
                try:
                    obj = json.loads(body)
                    if check:
                        check(obj)
                    return obj, body
                except (ValueError, KeyError, TypeError) as e:
                    errors += 1
                    self.note("bad_body", f"{method} {path} {e!r} {body[:120]!r}")
            else:
                errors += 1
                self.note("http_error", f"{method} {path} {status} {body[:120]!r}")
            if errors >= MAX_ERRORS:
                raise RuntimeError(f"giving up on {method} {path} after {errors} errors")
            time.sleep(min(0.25 * 2 ** errors, 5))

    def fetch_token(self):
        def check(o):
            if not isinstance(o["token"], str) or not o["token"]:
                raise ValueError("empty token")
        obj, _ = self.call("POST", "/token", check=check)
        self.note("token_issued", obj["token"])
        return obj["token"]


def write_atomic(path, data):
    tmp = path + ".tmp"
    with open(tmp, "wb") as f:
        f.write(data)
    os.replace(tmp, path)


def fetch_orders(data_dir):
    client = Client(os.path.join(data_dir, "events.log"))

    def check_for(n):
        def check(o):
            if not isinstance(o, dict):
                raise ValueError("not an object")
            for k in ("page", "total_pages", "items", "next"):
                if k not in o:
                    raise ValueError("missing " + k)
            if o["page"] != n:
                raise ValueError(f"asked for page {n}, got {o['page']}")
            if not isinstance(o["items"], list):
                raise ValueError("items is not a list")
        return check

    total = None
    n = 1
    while total is None or n <= total:
        path = os.path.join(data_dir, f"orders_page_{n:03d}.json")
        if os.path.exists(path):
            with open(path, "rb") as f:
                obj = json.load(f)
        else:
            obj, body = client.call("GET", f"/orders?page={n}", check=check_for(n))
            write_atomic(path, body)
        if total is None:
            total = obj["total_pages"]
        elif obj["total_pages"] != total:
            client.note("total_pages_changed", f"page {n}: {total} -> {obj['total_pages']}")
            total = max(total, obj["total_pages"])
        expected_next = f"/orders?page={n + 1}" if n < total else None
        if obj["next"] != expected_next:
            client.note("next_unexpected", f"page {n}: next={obj['next']!r} expected={expected_next!r}")
        n += 1
    print(f"fetched pages 1..{total}; events: {json.dumps(client.counts, sort_keys=True)}")


def fetch_customers(data_dir):
    client = Client(os.path.join(data_dir, "events.log"))
    with open(os.path.join(data_dir, "needed_customers.json")) as f:
        needed = json.load(f)
    cache_path = os.path.join(data_dir, "customers.json")
    cache = {}
    if os.path.exists(cache_path):
        with open(cache_path) as f:
            cache = json.load(f)

    def check_for(cid):
        def check(o):
            if not isinstance(o, dict):
                raise ValueError("not an object")
            for k in ("id", "name", "region", "tier", "discount_pct"):
                if k not in o:
                    raise ValueError("missing " + k)
            if o["id"] != cid:
                raise ValueError(f"asked for {cid}, got {o['id']}")
        return check

    for cid in needed:
        if cid in cache:
            continue
        obj, _ = client.call("GET", "/customers/" + urllib.parse.quote(cid, safe=""),
                             check=check_for(cid), not_found_ok=True)
        cache[cid] = obj
        write_atomic(cache_path, json.dumps(cache, sort_keys=True, indent=1).encode())
    print(f"customers cached: {len(cache)}/{len(needed)}; events: {json.dumps(client.counts, sort_keys=True)}")


def main(argv):
    if len(argv) != 3 or argv[1] not in ("fetch-orders", "fetch-customers"):
        print(__doc__)
        return 2
    data_dir = argv[2]
    os.makedirs(data_dir, exist_ok=True)
    {"fetch-orders": fetch_orders, "fetch-customers": fetch_customers}[argv[1]](data_dir)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

